// Neon Escape – simple endless runner on canvas#game

const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

// Player ship
const player = {
  x: canvas.width / 2,
  y: canvas.height * 0.8,
  w: 30,
  h: 40,
  speed: 5,
  boostSpeed: 10,
  boostEnergy: 100, // max 100
  boosting: false,
};

// Obstacles
const obstacles = [];
let obstacleTimer = 0;
const obstacleInterval = 90; // frames

let distance = 0;
let speed = 2; // tunnel scroll speed
let gameOver = false;

// Input handling
const keys = {};
window.addEventListener('keydown', e => { keys[e.code] = true; });
window.addEventListener('keyup', e => { keys[e.code] = false; });

function spawnObstacle() {
  const size = 40 + Math.random() * 30;
  const x = Math.random() * (canvas.width - size);
  obstacles.push({ x, y: -size, w: size, h: size });
}

function update() {
  if (gameOver) return;

  // Player movement
  if (keys['ArrowLeft']) player.x -= player.speed;
  if (keys['ArrowRight']) player.x += player.speed;

  // Boost handling
  if (keys['Space'] && player.boostEnergy > 0) {
    player.boosting = true;
    player.y -= player.boostSpeed;
    player.boostEnergy -= 2;
  } else {
    player.boosting = false;
    player.y += player.speed; // natural descent
    if (player.boostEnergy < 100) player.boostEnergy += 1; // regen
  }

  // Keep player inside canvas
  if (player.x < 0) player.x = 0;
  if (player.x + player.w > canvas.width) player.x = canvas.width - player.w;
  if (player.y < 0) player.y = 0;
  if (player.y + player.h > canvas.height) player.y = canvas.height - player.h;

  // Obstacle logic
  obstacleTimer++;
  if (obstacleTimer >= obstacleInterval) {
    spawnObstacle();
    obstacleTimer = 0;
    // Gradually increase tunnel speed
    speed += 0.02;
  }

  obstacles.forEach(o => o.y += speed);
  // Remove off‑screen obstacles
  while (obstacles.length && obstacles[0].y > canvas.height) obstacles.shift();

  // Collision detection
  for (const o of obstacles) {
    if (
      player.x < o.x + o.w &&
      player.x + player.w > o.x &&
      player.y < o.y + o.h &&
      player.y + player.h > o.y
    ) {
      gameOver = true;
    }
  }

  distance += speed;
}

function draw() {
  // Clear with neon background
  ctx.fillStyle = '#000020';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Draw player (glowing ship)
  ctx.fillStyle = '#00ffff';
  ctx.fillRect(player.x, player.y, player.w, player.h);

  // Draw obstacles (neon bars)
  ctx.fillStyle = '#ff00ff';
  obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));

  // UI – score & boost
  ctx.fillStyle = '#ffffff';
  ctx.font = '20px monospace';
  ctx.fillText(`Score: ${Math.floor(distance)}`, 20, 30);
  ctx.fillText(`Boost: ${Math.floor(player.boostEnergy)}`, 20, 60);

  if (gameOver) {
    ctx.fillStyle = 'rgba(255,0,0,0.7)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#fff';
    ctx.font = '48px monospace';
    ctx.fillText('Game Over', canvas.width / 2 - 120, canvas.height / 2);
  }
}

function loop() {
  update();
  draw();
  if (!gameOver) requestAnimationFrame(loop);
}

loop();
